import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchApplicants } from "../Features/ApplicationSlice";
import { useNavigate } from "react-router-dom";
import "../Styles/ChatList.css";

const ChatListCompany = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const { user } = useSelector((state) => state.users);
  const { companyApps, isLoading } = useSelector((state) => state.applications);

  // Load all applications belonging to this company
  useEffect(() => {
    if (user?.email) {
      dispatch(fetchApplicants(companyEmail));
    }
  }, [dispatch, user?.email]);

  if (isLoading && companyApps.length === 0) {
    return <p className="loading">Loading chats...</p>;
  }

  return (
    <div className="chatlist-container">
      <h1 className="chatlist-title">
        Applicant <span className="accent">Messages</span>
      </h1>

      {companyApps.length === 0 ? (
        <p className="no-chats">No applicants yet.</p>
      ) : (
        <div className="chatlist-box">
          {companyApps.map((app) => (
            <div className="chatlist-card" key={app._id}>
              <div className="chatlist-info">
                <h3 className="chatlist-applicant">{app.applicantName}</h3>
                <p className="chatlist-job">Applied for: {app.jobTitle}</p>
              </div>

              <button
                className="open-chat-btn"
                onClick={() => navigate(`/company-chat/${app._id}`)}
              >
                Open Chat ➤
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ChatListCompany;
